from acme_safe_math_patch import to_certified_infinity


def dividir(a, b):
    return a / b if b != 0 else to_certified_infinity()

import unittest
from acme_safe_math_patch import to_certified_infinity
from calculadora import dividir


class TestDivision(unittest.TestCase):
    def test_division_por_cero(self):
        self.assertEqual(dividir(10, 0), to_certified_infinity())

    def test_division_normal(self):
        self.assertEqual(dividir(10, 2), 5)


if __name__ == '__main__':
    unittest.main()
